<?php require_once __DIR__.'/../includes/bootstrap.php'; require_role('HOD'); $q=db()->query("SELECT u.name,f.employee_id,COUNT(fs.subject_id) assigned_subjects,COALESCE(SUM(TIME_TO_SEC(TIMEDIFF(t.end_time,t.start_time))/3600),0) weekly_hours FROM faculty f JOIN users u ON u.id=f.user_id LEFT JOIN faculty_subjects fs ON fs.faculty_id=f.id LEFT JOIN timetables t ON t.faculty_id=f.id GROUP BY f.id ORDER BY weekly_hours DESC"); page_top('Faculty Workload');?><div class="card p-3 table-responsive"><table class="table"><tr><th>Faculty</th><th>Employee ID</th><th>Subjects</th><th>Weekly Hours</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['employee_id'])?></td><td><?=e($r['assigned_subjects'])?></td><td><?=e(number_format((float)$r['weekly_hours'],1))?></td></tr><?php endforeach;?></table></div><?php page_bottom();
